import { render, screen } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import '@testing-library/jest-dom';
import { LoginForm } from './LoginForm';
import { login, type LoginResponse } from '../services/authApi';

jest.mock('../services/authApi');
const mockedLogin = jest.mocked(login);

describe('LoginForm', () => {
  beforeEach(() => {
    mockedLogin.mockReset();
  });

  it('renderiza o formulário de login inicialmente', () => {
    render(<LoginForm />);

    expect(screen.getByLabelText('E-mail')).toHaveValue('');
    expect(screen.getByLabelText('Senha')).toHaveValue('');
    expect(screen.queryByRole('alert')).not.toBeInTheDocument();
  });

  it('exibe erro para e-mail inválido', async () => {
    const user = userEvent.setup();
    render(<LoginForm />);

    await user.type(screen.getByLabelText('E-mail'), 'invalid-email');
    await user.click(screen.getByRole('button', { name: 'Entrar' }));

    const alerts = screen.getAllByRole('alert');
    expect(alerts).toHaveLength(2);
    expect(alerts[0]).toHaveTextContent('E-mail inválido.');
    expect(alerts[1]).toHaveTextContent('Informe a senha.');
  });

  it('exibe erro para senha abaixo do comprimento mínimo', async () => {
    const user = userEvent.setup();
    render(<LoginForm />);

    await user.type(screen.getByLabelText('E-mail'), 'test@example.com');
    await user.type(screen.getByLabelText('Senha'), '123');
    await user.click(screen.getByRole('button', { name: 'Entrar' }));

    expect(screen.getByRole('alert')).toHaveTextContent('A senha deve ter pelo menos 8 caracteres.');
  });

  it('exibe erro para campos vazios', async () => {
    const user = userEvent.setup();
    render(<LoginForm />);

    await user.click(screen.getByRole('button', { name: 'Entrar' }));

    const alerts = screen.getAllByRole('alert');
    expect(alerts).toHaveLength(2);
    expect(alerts[0]).toHaveTextContent('Informe o e-mail.');
    expect(alerts[1]).toHaveTextContent('Informe a senha.');
  });

  it('submete o formulário com sucesso', async () => {
    const user = userEvent.setup();
    const onSuccess = jest.fn();
    mockedLogin.mockResolvedValue({ token: 'abc123', user: { id: 1, name: 'John Doe' } });
    render(<LoginForm onSuccess={onSuccess} />);

    await user.type(screen.getByLabelText('E-mail'), 'test@example.com');
    await user.type(screen.getByLabelText('Senha'), 'password123');
    await user.click(screen.getByRole('button', { name: 'Entrar' }));

    expect(await screen.findByRole('status')).toHaveTextContent('Bem-vindo, John Doe!');
    expect(onSuccess).toHaveBeenCalledWith({ token: 'abc123', user: { id: 1, name: 'John Doe' } });
  });

  it('exibe mensagem de erro da API', async () => {
    const user = userEvent.setup();
    mockedLogin.mockRejectedValue(new Error('Erro de autenticação'));
    render(<LoginForm />);

    await user.type(screen.getByLabelText('E-mail'), 'test@example.com');
    await user.type(screen.getByLabelText('Senha'), 'password123');
    await user.click(screen.getByRole('button', { name: 'Entrar' }));

    expect(await screen.findByRole('alert')).toHaveTextContent('Erro de autenticação');
  });

  it('desabilita botão de submit durante carregamento', async () => {
    let finish!: (response: LoginResponse) => void;
    mockedLogin.mockImplementation(() => new Promise<LoginResponse>((resolve) => { finish = resolve; }));
    const user = userEvent.setup();
    render(<LoginForm />);

    await user.type(screen.getByLabelText('E-mail'), 'test@example.com');
    await user.type(screen.getByLabelText('Senha'), 'password123');
    await user.click(screen.getByRole('button', { name: 'Entrar' }));

    expect(screen.getByRole('button', { name: 'Entrando...' })).toBeDisabled();
    finish({ token: 'abc123', user: { id: 1, name: 'John Doe' } });
  });

  it('caso de borda com e-mail e senha vazios', async () => {
    const user = userEvent.setup();
    render(<LoginForm />);

    await user.click(screen.getByRole('button', { name: 'Entrar' }));

    const alerts = screen.getAllByRole('alert');
    expect(alerts).toHaveLength(2);
    expect(alerts[0]).toHaveTextContent('Informe o e-mail.');
    expect(alerts[1]).toHaveTextContent('Informe a senha.');
  });
});
